package com.meddibuddy.appointment.service;
import com.meddibuddy.appointment.*;import com.meddibuddy.doctor.DoctorDto;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.LocalDate;import java.util.List;
@Service public class AppointmentService {private final AppointmentRepository repo;public AppointmentService(AppointmentRepository repo){this.repo=repo;}@Transactional public Appointment book(String email,DoctorDto d,LocalDate date,String time,String reason){if(!date.isAfter(LocalDate.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Appointment date must be in the future");if(repo.existsByDoctorIdAndAppointmentDateAndAppointmentTimeAndStatusNot(d.id(),date,time,"CANCELLED"))throw new ResponseStatusException(HttpStatus.CONFLICT,"That time is already booked");Appointment a=new Appointment();a.setPatientEmail(email);a.setDoctorId(d.id());a.setDoctorName(d.name());a.setSpecialty(d.specialty());a.setAppointmentDate(date);a.setAppointmentTime(time);a.setFee(d.fee());a.setReason(reason);return repo.save(a);}public long count(){return repo.count();}public List<Appointment> findMine(String email){return repo.findByPatientEmailOrderByAppointmentDateDesc(email);}public Appointment cancel(Long id,String email){Appointment a=repo.findById(id).filter(x->x.getPatientEmail().equalsIgnoreCase(email)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!List.of("PENDING","CONFIRMED").contains(a.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Appointment can no longer be cancelled");a.setStatus("CANCELLED");return repo.save(a);}}

